'use client';
import { useState } from 'react';

export default function Navbar({ aiOnline }) {
  const [active, setActive] = useState('dashboard');
  const links = [
    { id: 'dashboard', label: 'Dashboard' },
    { id: 'alerts', label: 'Alerts' },
    { id: 'settings', label: 'Settings' },
  ];

  return (
    <nav className="navbar">
      <div className="nav-brand">
        <div className="nav-brand-mark">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
            <path d="M12 3L4 7v5c0 4.5 3.4 8.7 8 9.9 4.6-1.2 8-5.4 8-9.9V7l-8-4z"
              stroke="#63ca84" strokeWidth="1.5" strokeLinejoin="round"/>
            <circle cx="12" cy="12" r="3" stroke="#63ca84" strokeWidth="1.5"/>
          </svg>
        </div>
        <div>
          <div className="nav-brand-name">Criminal Detector AI</div>
          <div className="nav-brand-ver">v4.2.1 · Neural Surveillance</div>
        </div>
      </div>

      <div className="nav-links">
        {links.map(l => (
          <button
            key={l.id}
            className={`nav-link${active === l.id ? ' active' : ''}`}
            onClick={() => setActive(l.id)}
          >
            {l.label}
          </button>
        ))}
      </div>

      <div className="nav-ai-badge">
        <div className={`pulse-dot${aiOnline ? '' : ' red'}`} />
        AI {aiOnline ? 'ONLINE' : 'OFFLINE'}
      </div>
    </nav>
  );
}
